/**
 * Shared visual + textual mappers for audit-style rows.
 *
 * Used by:
 *   * ``/doc-net/activities``                  — org-wide audit feed.
 *   * ``/doc-net/missions/:id/timeline``       — per-mission timeline.
 *   * ``Dashboard/widgets/lists/RecentActivity`` — embedded widget.
 *
 * Why a shared module:
 *   The activity page evolved a rich set of icon/color/action mappings
 *   that the per-mission timeline would otherwise duplicate (and drift
 *   from over time).  These are pure functions with no Vue dependency
 *   so they can be reused anywhere — tests, widgets, future tooling.
 *
 * Pure-function rules:
 *   * No ``$t`` baked in — callers pass a translator.  Lets the
 *     module be unit-tested with a synchronous fake.
 *   * No ``router`` baked in — navigation is page-specific (the
 *     activities page navigates to the entity; the timeline page
 *     stays put).
 */

/** Pretty-print an entity_type for display (e.g. "issue" → "Issues"). */
export function formatEntityType(
  type: string | undefined,
  t: (key: string) => string,
): string {
  if (!type) return '';
  // Map to existing i18n keys where one exists; fall back to title-cased
  // raw type so unknown entities still render readably.
  const i18nKeys: Record<string, string> = {
    issue: 'issues',
    subtask: 'subtasks',
    mission: 'missions',
    project: 'projects',
    agent: 'agents',
    agent_run: 'agent_run',
    email: 'emails',
    label: 'labels',
    approval: 'approvals',
    attachment: 'attachments',
    inbox_item: 'inbox',
  };
  const key = i18nKeys[type];
  if (!key) {
    return type.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
  }
  const translated = t(key);
  // Tolgee returns the key on miss — fall back to the raw form so we
  // never display the i18n key name itself ("missions" wins, not
  // "missions" + braces).
  return translated === key
    ? type.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase())
    : translated;
}

/** Material icon name for an entity_type. */
export function entityIcon(type: string | undefined): string {
  if (!type) return 'article';
  const icons: Record<string, string> = {
    issue: 'task',
    subtask: 'checklist',
    mission: 'rocket_launch',
    project: 'folder_open',
    agent: 'smart_toy',
    agent_run: 'play_circle',
    email: 'mail_outline',
    label: 'label',
    approval: 'verified',
    attachment: 'attach_file',
    inbox_item: 'inbox',
  };
  return icons[type] || 'article';
}

/** Quasar color name for an entity_type.  Used for the entity badge. */
export function entityColor(type: string | undefined): string {
  if (!type) return 'grey';
  const colors: Record<string, string> = {
    issue: 'negative',
    mission: 'mission',
    project: 'project',
    agent: 'positive',
    agent_run: 'positive',
    email: 'warning',
    inbox_item: 'primary',
  };
  return colors[type] || 'grey';
}

/** Pretty-print an audit ``action`` string with i18n fallback. */
export function formatAction(
  action: string,
  t: (key: string) => string,
): string {
  const translated = t(action);
  // ``$t`` returns the key itself when no translation exists.  Fall
  // back to title-cased raw action so the row never displays a bare
  // i18n key like "run_succeeded".
  if (translated === action) {
    return action.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
  }
  return translated;
}

/** Quasar color for an action.  Reflects success/failure semantics:
 *  green = succeeded/created, red = failed/rejected, grey = neutral. */
export function actionColor(action: string): string {
  if (['created', 'ingested'].includes(action)) return 'positive';
  if (
    [
      'updated',
      'toggled',
      'classification_changed',
      'project_assigned',
      'config_rollback',
    ].includes(action)
  ) {
    return 'primary';
  }
  if (action === 'deleted') return 'negative';
  if (
    ['approved', 'run_completed', 'run_succeeded', 'succeeded', 'acted:approve'].includes(
      action,
    )
  ) {
    return 'positive';
  }
  if (['rejected', 'run_failed', 'acted:reject'].includes(action)) return 'negative';
  if (['run_created', 'run_stopped'].includes(action)) return 'info';
  if (['marked_read', 'marked_unread'].includes(action)) return 'grey';
  if (action === 'acted:comment') return 'warning';
  // Mission conversation — mirror the colors used by the
  // mission-detail conversation panel so a user message reads
  // the same in both surfaces:
  //   * ``user_message`` → orange (warm = human-authored).
  //     Without this override the row falls through to the
  //     ``grey`` default and visually groups with agent
  //     content, which is the opposite of what we want — the
  //     user's input is the most attention-worthy event on
  //     the timeline.
  //   * ``agent_response`` → primary blue, matching the
  //     orchestrator's tool-call rows so agent output reads
  //     as one cohesive stream.
  if (action === 'user_message') return 'orange';
  if (action === 'agent_response') return 'primary';
  // Tool events — used by the timeline page.
  if (action === 'tool_call') return 'info';
  if (action === 'tool_result') return 'positive';
  if (action === 'status_changed') return 'primary';
  return 'grey';
}

/** Material icon name for an action. */
export function actionIcon(action: string): string {
  const icons: Record<string, string> = {
    created: 'add_circle_outline',
    updated: 'edit',
    deleted: 'delete_outline',
    toggled: 'toggle_on',
    marked_read: 'mark_email_read',
    marked_unread: 'mark_email_unread',
    ingested: 'download',
    classification_changed: 'category',
    project_assigned: 'assignment',
    config_rollback: 'history',
    approved: 'check_circle',
    rejected: 'cancel',
    run_created: 'play_arrow',
    run_completed: 'task_alt',
    run_failed: 'error_outline',
    run_stopped: 'stop_circle',
    succeeded: 'check_circle',
    'acted:approve': 'thumb_up',
    'acted:reject': 'thumb_down',
    'acted:comment': 'chat_bubble_outline',
    // Tool/timeline-specific.
    tool_call: 'build',
    tool_result: 'check_circle',
    status_changed: 'swap_horiz',
    issue_created: 'add_circle',
    comment_added: 'chat_bubble_outline',
    commented: 'chat_bubble_outline',
    // Mission conversation rows — match the conversation
    // panel's avatars: ``person`` for the human, ``smart_toy``
    // (robot) for the agent.  Two distinct icons + the colors
    // wired in ``actionColor`` mean the timeline reader sees
    // "human" vs "agent" at peripheral-vision distance.
    user_message: 'person',
    agent_response: 'smart_toy',
  };
  return icons[action] || 'circle';
}

/**
 * Inline diff text for a single-field change ("in_progress → in_review").
 *
 * Returns ``''`` when:
 *   * Either side is missing.
 *   * More than one key changed (we'd lie about which one to show).
 *   * The values aren't primitives (showing object → object is noise).
 *
 * Both audit-page and timeline-page rows have a deltable shape:
 *   * Audit: ``entry.old_values`` / ``entry.new_values``.
 *   * Timeline: ``event.payload.old`` / ``event.payload.new``.
 *
 * The shared helper takes the two halves directly so the caller picks
 * the right keys for its data model.
 */
export function inlineChange(
  oldValues: Record<string, unknown> | null | undefined,
  newValues: Record<string, unknown> | null | undefined,
): string {
  if (!oldValues || !newValues) return '';
  const keys = Object.keys(newValues).filter(
    (k) => oldValues[k] !== undefined,
  );
  if (keys.length !== 1) return '';
  const key = keys[0];
  const from = oldValues[key];
  const to = newValues[key];
  if (typeof from === 'object' || typeof to === 'object') return '';
  return `${from} → ${to}`;
}

/**
 * Single-field delta as the raw pair ``{key, from, to}`` instead of
 * pre-formatted text.  Lets callers render the values their way —
 * e.g. status flips render with ``<StatusBadge>`` for visual parity
 * with mission/issue cards, while non-status deltas can fall back to
 * inline text.  Returns ``null`` under the same conditions
 * ``inlineChange`` returns ``''``: missing sides, multi-field
 * change, or non-primitive values.
 */
export function inlineChangePair(
  oldValues: Record<string, unknown> | null | undefined,
  newValues: Record<string, unknown> | null | undefined,
): { key: string; from: string; to: string } | null {
  if (!oldValues || !newValues) return null;
  const keys = Object.keys(newValues).filter(
    (k) => oldValues[k] !== undefined,
  );
  if (keys.length !== 1) return null;
  const key = keys[0];
  const from = oldValues[key];
  const to = newValues[key];
  if (typeof from === 'object' || typeof to === 'object') return null;
  return { key, from: String(from), to: String(to) };
}

/** Truncate ``text`` to ``maxLen`` chars, appending an ellipsis if cut. */
export function truncate(text: string, maxLen: number): string {
  if (!text) return '';
  if (text.length <= maxLen) return text;
  return text.slice(0, maxLen).trimEnd() + '…';
}
